return {
  apply(ctx) {
    const shell = ctx.get('shell')
    const fs = ctx.get('fs')
    if (shell === undefined) return

    // ！导入到其他电脑时，把这几个常量改成新机器的实际路径！
    const ROOT = 'C:\\Users\\Administrator\\project\\deepseek-workspace'
    const TOOLS = ROOT + '\\.dsh-tools'
    const PYLIBS = TOOLS + '\\pylibs'
    const MODEL_DIR = TOOLS + '\\whisper-model'
    const PYTHON = 'C:\\Users\\Administrator\\AppData\\Local\\Programs\\Python\\Python311\\python.exe'
    const WHISPER = 'C:\\Users\\Administrator\\AppData\\Local\\Programs\\Python\\Python311\\Scripts\\whisper.exe'
    const FFMPEG = 'C:\\soft\\www.gyan.dev-ffmpeg-2024-08-26-essentials_build\\ffmpeg-2024-08-26-git-98610fe95f-essentials_build\\bin\\ffmpeg.exe'
    const SEG_SECONDS = 120
    const ERROR_LOG = TOOLS + '\\bili-work\\last-error.txt'

    const jobs = new Map()
    let seq = 0
    let currentJobId = null
    let currentUrl = ''

    async function runCmd(command, timeoutMs) {
      // 显式传 workdir 与 sandboxPolicy：pwsh-sandbox 无 policy 时回退到
      // harness 启动目录，ACL 沙箱会拒绝写工作区文件（历史坑，见 docs/踩坑记录.md）。
      const spec = shell.resolve({
        command,
        workdir: ROOT,
        timeoutMs: timeoutMs || 120000,
        stdoutMaxBytes: 64 * 1024 * 1024,
        sandboxPolicy: { mode: 'workspace-write', workspaceRoot: ROOT },
      })
      const res = await shell.run(spec)
      if (res.sandbox && res.sandbox.denied) {
        throw new Error('命令被沙箱拒绝: ' + String(res.stderr && res.stderr.text || '').slice(0, 300))
      }
      if (res.exitCode !== 0) {
        throw new Error('命令失败 (exit ' + res.exitCode + '): ' + String(res.stderr && res.stderr.text || '').slice(0, 400))
      }
      return res
    }

    async function writeErrorLog(text) {
      try {
        if (fs !== undefined) {
          const target = await fs.resolve(ERROR_LOG, { cwd: ROOT })
          const policy = { mode: 'workspace-write', workspaceRoot: ROOT }
          await fs.writeText(target, text, undefined, undefined, policy)
        }
      } catch (e) {
        // 落盘失败不阻塞主流程
      }
    }

    function extractBv(input) {
      const m = String(input || '').match(/BV[0-9A-Za-z]{10}/)
      return m ? m[0] : null
    }

    function q(s) { return "'" + String(s).replace(/'/g, "''") + "'" }

    function fmtTime(sec) {
      sec = Math.max(0, Math.floor(Number(sec) || 0))
      const h = Math.floor(sec / 3600)
      const m = Math.floor((sec % 3600) / 60)
      const s = sec % 60
      const mm = String(m).padStart(2, '0')
      const ss = String(s).padStart(2, '0')
      return h > 0 ? h + ':' + mm + ':' + ss : mm + ':' + ss
    }

    function groupParagraphs(segs) {
      const paras = []
      let cur = null
      for (const s of segs) {
        const text = String(s.text || '').trim()
        if (!text) continue
        if (!cur) {
          cur = { start: s.start, end: s.end, texts: [text] }
        } else {
          const gap = s.start - cur.end
          const last = cur.texts[cur.texts.length - 1]
          const ends = /[。！？!?；;…]$/.test(last)
          const span = cur.end - cur.start
          const chars = cur.texts.join('').length
          if (gap > 3 || (ends && gap > 0.8) || span >= 45 || chars >= 160) {
            paras.push(cur)
            cur = { start: s.start, end: s.end, texts: [text] }
          } else {
            cur.end = s.end
            cur.texts.push(text)
          }
        }
      }
      if (cur) paras.push(cur)
      return paras.map((p) => ({ start: p.start, end: p.end, text: p.texts.join('') }))
    }

    async function runJob(job) {
      try {
        job.stage = '获取视频信息与字幕'
        const biliCmd = '$env:PYTHONPATH=' + q(PYLIBS) + "; $env:PYTHONIOENCODING='utf-8'; & " + q(PYTHON) + " -c 'from bili_cli.cli import cli; cli()' video " + job.bv + ' --subtitle-timeline --json'
        const res = await runCmd(biliCmd, 60000)
        let parsed = null
        try { parsed = JSON.parse(String(res.stdout && res.stdout.text || '').trim()) } catch (e) { parsed = null }
        const title = parsed && parsed.data && parsed.data.video ? parsed.data.video.title : job.bv
        const subtitle = parsed && parsed.data ? parsed.data.subtitle : null
        const items = subtitle && subtitle.available && Array.isArray(subtitle.items) ? subtitle.items : []

        if (items.length > 0) {
          const segs = items.map((it) => ({ start: Number(it.from) || 0, end: Number(it.to) || 0, text: String(it.content || '') }))
          const paragraphs = groupParagraphs(segs)
          const text = paragraphs.map((p) => '[' + fmtTime(p.start) + '] ' + p.text).join('\n')
          job.result = { title, source: 'subtitle', paragraphs, text }
          job.stage = '完成'
          job.done = true
          return
        }

        const workDir = TOOLS + '\\bili-work\\' + job.jobId
        job.stage = '下载音频'
        await runCmd('New-Item -ItemType Directory -Force -Path ' + q(workDir) + ' | Out-Null', 30000)
        const dlCmd = '$env:PYTHONPATH=' + q(PYLIBS) + "; $env:PYTHONIOENCODING='utf-8'; & " + q(PYTHON) + " -c 'from bili_cli.cli import cli; cli()' audio " + job.bv + ' --no-split -o ' + q(workDir)
        await runCmd(dlCmd, 300000)

        const m4aOut = await runCmd('Get-ChildItem -LiteralPath ' + q(workDir) + " -Filter '*.m4a' | Select-Object -First 1 -ExpandProperty FullName", 30000)
        const m4aPath = String(m4aOut.stdout && m4aOut.stdout.text || '').trim()
        if (!m4aPath) throw new Error('未找到下载的音频文件')

        job.stage = '切分音频'
        await runCmd('& ' + q(FFMPEG) + ' -y -i ' + q(m4aPath) + ' -f segment -segment_time ' + SEG_SECONDS + ' -ac 1 -ar 16000 ' + q(workDir + '\\seg_%03d.wav'), 300000)

        const listOut = await runCmd('Get-ChildItem -LiteralPath ' + q(workDir) + " -Filter 'seg_*.wav' | Sort-Object Name | ForEach-Object { $_.Name }", 30000)
        const names = String(listOut.stdout && listOut.stdout.text || '').split(/\r?\n/).map((s) => s.trim()).filter(Boolean)
        if (names.length === 0) throw new Error('音频切分失败')

        job.stage = '语音识别'
        const all = []
        for (let i = 0; i < names.length; i++) {
          job.progress = { current: i, total: names.length }
          const wav = workDir + '\\' + names[i]
          const base = names[i].replace(/\.wav$/i, '')
          await runCmd('& ' + q(WHISPER) + ' ' + q(wav) + ' --model base --model_dir ' + q(MODEL_DIR) + ' --language zh --output_format json --output_dir ' + q(workDir) + ' --fp16 False', 300000)
          const jsonOut = await runCmd('Get-Content -LiteralPath ' + q(workDir + '\\' + base + '.json') + ' -Raw -Encoding UTF8', 30000)
          let data = null
          try { data = JSON.parse(String(jsonOut.stdout && jsonOut.stdout.text || '')) } catch (e) { data = null }
          const offset = i * SEG_SECONDS
          for (const s of (data && Array.isArray(data.segments) ? data.segments : [])) {
            const t = String(s.text || '').trim()
            if (!t) continue
            all.push({ start: (Number(s.start) || 0) + offset, end: (Number(s.end) || 0) + offset, text: t })
          }
        }
        job.progress = null
        job.stage = '整理文本'
        const paragraphs = groupParagraphs(all)
        const text = paragraphs.map((p) => '[' + fmtTime(p.start) + '] ' + p.text).join('\n')
        job.result = { title, source: 'asr', paragraphs, text }
        job.stage = '完成'
        job.done = true
      } catch (err) {
        job.error = String((err && err.message) || err)
        job.stage = '失败'
        job.done = true
        const log = 'job=' + job.jobId + ' bv=' + job.bv + ' stage=' + job.stage + '\n' + job.error
        writeErrorLog(log)
      }
    }

    harness.handle('bili.start', async (args) => {
      const url = args && args.url ? String(args.url) : ''
      const bv = extractBv(url)
      if (!bv) return { ok: false, error: '无法从链接中识别 BV 号' }
      const jobId = 'bili-' + (++seq)
      const job = { jobId, bv, stage: '开始', done: false, error: null, result: null, progress: null }
      jobs.set(jobId, job)
      currentJobId = jobId
      currentUrl = url
      runJob(job)
      return { ok: true, jobId }
    })

    harness.handle('bili.status', async (args) => {
      const job = jobs.get(args && args.jobId)
      if (!job) return { ok: false, error: '任务不存在' }
      return { ok: true, stage: job.stage, done: job.done, error: job.error, result: job.result, progress: job.progress }
    })

    harness.handle('bili.current', async () => {
      const job = jobs.get(currentJobId)
      if (!job) return { ok: true, jobId: null, url: '' }
      return {
        ok: true,
        jobId: currentJobId,
        url: currentUrl,
        status: { ok: true, stage: job.stage, done: job.done, error: job.error, result: job.result, progress: job.progress },
      }
    })

    harness.handle('bili.errorLog', async () => {
      try {
        if (fs === undefined) return { ok: true, content: '' }
        const target = await fs.resolve(ERROR_LOG, { cwd: ROOT })
        const info = await fs.stat(target)
        if (!info) return { ok: true, content: '' }
        const text = await fs.readText(target)
        return { ok: true, content: text }
      } catch (e) {
        return { ok: false, error: String((e && e.message) || e) }
      }
    })
  },
}

