return {
  inject: ['timer'],
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return

    styles.insert(`
      .dsw-bili-root { height: 100%; overflow-y: auto; padding: 16px 20px 40px; box-sizing: border-box; color: var(--dsw-alias-label-primary); background: var(--dsw-alias-bg-base); font-size: 14px; line-height: 1.6; }
      .dsw-bili-header { display: flex; align-items: baseline; gap: 10px; margin-bottom: 12px; }
      .dsw-bili-title-lg { font-size: 18px; font-weight: 600; }
      .dsw-bili-desc { font-size: 12px; color: var(--dsw-alias-label-secondary); }
      .dsw-bili-form { display: flex; gap: 8px; margin-bottom: 10px; }
      .dsw-bili-input { flex: 1; min-width: 0; padding: 7px 10px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font-size: 13px; box-sizing: border-box; }
      .dsw-bili-input:focus { outline: none; border-color: var(--dsw-alias-brand-primary); }
      .dsw-bili-btn { padding: 7px 14px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font-size: 13px; cursor: pointer; white-space: nowrap; }
      .dsw-bili-btn:hover { border-color: var(--dsw-alias-border-l2); }
      .dsw-bili-btn-primary { background: var(--dsw-alias-brand-primary); color: #fff; border-color: transparent; }
      .dsw-bili-btn-primary:disabled { opacity: 0.6; cursor: not-allowed; }
      .dsw-bili-status { margin-bottom: 10px; padding: 8px 12px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); font-size: 13px; }
      .dsw-bili-progress { margin-top: 6px; height: 4px; border-radius: 2px; background: var(--dsw-alias-border-l1); overflow: hidden; }
      .dsw-bili-progress > div { height: 100%; background: var(--dsw-alias-brand-primary); }
      .dsw-bili-error { color: var(--dsw-alias-state-error-primary); }
      .dsw-bili-result-title { font-weight: 600; margin-bottom: 4px; font-size: 15px; }
      .dsw-bili-result-meta { font-size: 12px; color: var(--dsw-alias-label-secondary); margin-bottom: 10px; }
      .dsw-bili-result-actions { display: flex; gap: 8px; margin-bottom: 12px; }
      .dsw-bili-paras { display: flex; flex-direction: column; gap: 10px; }
      .dsw-bili-para { padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); }
      .dsw-bili-para-time { color: var(--dsw-alias-brand-primary); font-family: ui-monospace, Consolas, monospace; font-size: 12px; font-weight: 600; margin-right: 8px; }
      .dsw-bili-para-text { white-space: pre-wrap; word-break: break-word; }
      .dsw-bili-empty { color: var(--dsw-alias-label-secondary); text-align: center; padding: 32px 0; }
      .dsw-bili-hint { font-size: 12px; color: var(--dsw-alias-label-secondary); margin-top: 8px; }
    `)

    function BiliView() {
      const h = React.createElement
      const [url, setUrl] = React.useState('')
      const [jobId, setJobId] = React.useState(null)
      const [status, setStatus] = React.useState(null)
      const [busy, setBusy] = React.useState(false)
      const [copied, setCopied] = React.useState(false)

      // 挂载时恢复最近一次任务：conversation.view 切换标签会卸载本组件，
      // 切回时重新挂载；任务在 Host 端仍在跑，这里重新绑定轮询。
      React.useEffect(() => {
        let alive = true
        host.call('bili.current').then((r) => {
          if (!alive) return
          if (r && r.ok && r.jobId) {
            setUrl(r.url || '')
            setJobId(r.jobId)
            setStatus(r.status || null)
          }
        }).catch(() => {})
        return () => { alive = false }
      }, [])

      React.useEffect(() => {
        if (!jobId) return undefined
        const disposer = ctx.interval(() => {
          host.call('bili.status', { jobId }).then((s) => {
            setStatus(s)
            if (s && s.done) setJobId(null)
          }).catch(() => {})
        }, 1200)
        return () => { if (disposer) disposer() }
      }, [jobId])

      const start = () => {
        const u = url.trim()
        if (!u || busy) return
        setBusy(true)
        setStatus(null)
        setCopied(false)
        host.call('bili.start', { url: u }).then((r) => {
          setBusy(false)
          if (r && r.ok) setJobId(r.jobId)
          else setStatus({ ok: false, error: (r && r.error) || '启动失败' })
        }).catch((e) => {
          setBusy(false)
          setStatus({ ok: false, error: String((e && e.message) || e) })
        })
      }

      const copyAll = () => {
        const text = status && status.result ? status.result.text : ''
        if (!text) return
        const ok = () => { setCopied(true); ctx.timeout(() => setCopied(false), 1500) }
        try {
          if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(ok).catch(ok)
          } else {
            ok()
          }
        } catch (e) {
          ok()
        }
      }

      const running = busy || (jobId !== null && !(status && status.done))
      const progress = status && status.progress && status.progress.total
        ? Math.round((status.progress.current / status.progress.total) * 100)
        : 0
      const result = status && status.result ? status.result : null

      return h('div', { className: 'dsw-bili-root' },
        h('div', { className: 'dsw-bili-header' },
          h('div', { className: 'dsw-bili-title-lg' }, '视频转写'),
          h('div', { className: 'dsw-bili-desc' }, '粘贴 B 站链接，自动提取字幕；无字幕则下载音频并语音识别，输出带段落时间标注的文本'),
        ),
        h('div', { className: 'dsw-bili-form' },
          h('input', { className: 'dsw-bili-input', value: url, onChange: (e) => setUrl(e.target.value), onKeyDown: (e) => { if (e.key === 'Enter') start() }, placeholder: 'https://www.bilibili.com/video/BV...' }),
          h('button', { className: 'dsw-bili-btn dsw-bili-btn-primary', onClick: start, disabled: running }, running ? '处理中…' : '开始转写'),
        ),
        status && status.error && !status.ok
          ? h('div', { className: 'dsw-bili-status dsw-bili-error' }, status.error)
          : null,
        status && status.stage && !(status.done && status.result)
          ? h('div', { className: 'dsw-bili-status' },
              h('div', null, status.stage),
              status.progress && status.progress.total
                ? h('div', { className: 'dsw-bili-progress' }, h('div', { style: { width: progress + '%' } }))
                : null,
            )
          : null,
        result
          ? h('div', null,
              h('div', { className: 'dsw-bili-result-title' }, result.title),
              h('div', { className: 'dsw-bili-result-meta' }, (result.source === 'subtitle' ? '来源：视频字幕' : '来源：语音识别 (whisper)') + ' · ' + result.paragraphs.length + ' 段'),
              h('div', { className: 'dsw-bili-result-actions' },
                h('button', { className: 'dsw-bili-btn', onClick: copyAll }, copied ? '已复制 ✓' : '复制全文'),
              ),
              h('div', { className: 'dsw-bili-paras' },
                result.paragraphs.map((p) => h('div', { key: String(p.start), className: 'dsw-bili-para' },
                  h('span', { className: 'dsw-bili-para-time' }, '[' + fmtTime(p.start) + ']'),
                  h('span', { className: 'dsw-bili-para-text' }, p.text),
                )),
              ),
            )
          : (!running ? h('div', { className: 'dsw-bili-empty' }, '粘贴一个 B 站视频链接，点击「开始转写」') : null),
        h('div', { className: 'dsw-bili-hint' }, '提示：视频有字幕时直接提取；无字幕或未登录时自动下载音频并用 whisper 识别，25 分钟视频约需数分钟。'),
      )
    }

    function fmtTime(sec) {
      sec = Math.max(0, Math.floor(Number(sec) || 0))
      const h = Math.floor(sec / 3600)
      const m = Math.floor((sec % 3600) / 60)
      const s = sec % 60
      const mm = String(m).padStart(2, '0')
      const ss = String(s).padStart(2, '0')
      return h > 0 ? h + ':' + mm + ':' + ss : mm + ':' + ss
    }

    slots.inject('conversation.view', () => slots.register(
      { name: 'conversation.view', id: 'bili', order: 30, label: '视频转写' },
      () => React.createElement(BiliView, null),
    ))
  },
}
